-- PKG_DMF0072 — 클라우드 현재 상태 점검 (SCM_MGR · 조회 전용 · 변경 없음)
-- VERDICT: PRE=사내 적용 전과 동일 → 해당 파일 적용 / POST=이미 적용 → SKIP / ABSENT=없음 / DIFF=클라우드 본문이 다름 → 전체교체 금지·결과 공유
SET PAGESIZE 200 LINESIZE 300
COLUMN OBJ FORMAT A48
COLUMN VERDICT FORMAT A60

-- [A] 교체 대상 객체
SELECT 'PKG_DMF0072' OBJ, 'PACKAGE' TYP, '10_SPEC.sql' FILE_NM,
       (SELECT STATUS FROM USER_OBJECTS WHERE OBJECT_NAME = 'PKG_DMF0072' AND OBJECT_TYPE = 'PACKAGE') CLOUD_STATUS,
       CASE WHEN NOT EXISTS (SELECT 1 FROM USER_OBJECTS WHERE OBJECT_NAME = 'PKG_DMF0072' AND OBJECT_TYPE = 'PACKAGE') THEN 'ABSENT → ⚠ 기존 객체 부재: 선행 이관 필요'
            WHEN H.S = 181195672884 THEN 'POST → 이미 적용됨(SKIP)'
            WHEN H.S = 113376155428 THEN 'PRE → 적용 대상'
            ELSE 'DIFF → ⚠ 클라우드 본문이 사내와 다름: 전체교체 금지·결과 공유' END VERDICT
  FROM (SELECT SUM(ORA_HASH(RTRIM(TEXT, CHR(10)||CHR(13)||CHR(32)||CHR(9)))) S FROM USER_SOURCE WHERE NAME = 'PKG_DMF0072' AND TYPE = 'PACKAGE' AND LINE > 1) H;
SELECT 'PKG_DMF0072' OBJ, 'PACKAGE BODY' TYP, '11_BODY.sql' FILE_NM,
       (SELECT STATUS FROM USER_OBJECTS WHERE OBJECT_NAME = 'PKG_DMF0072' AND OBJECT_TYPE = 'PACKAGE BODY') CLOUD_STATUS,
       CASE WHEN NOT EXISTS (SELECT 1 FROM USER_OBJECTS WHERE OBJECT_NAME = 'PKG_DMF0072' AND OBJECT_TYPE = 'PACKAGE BODY') THEN 'ABSENT → ⚠ 기존 객체 부재: 선행 이관 필요'
            WHEN H.S = 1782847192264 THEN 'POST → 이미 적용됨(SKIP)'
            WHEN H.S = 1457821808412 THEN 'PRE → 적용 대상'
            ELSE 'DIFF → ⚠ 클라우드 본문이 사내와 다름: 전체교체 금지·결과 공유' END VERDICT
  FROM (SELECT SUM(ORA_HASH(RTRIM(TEXT, CHR(10)||CHR(13)||CHR(32)||CHR(9)))) S FROM USER_SOURCE WHERE NAME = 'PKG_DMF0072' AND TYPE = 'PACKAGE BODY' AND LINE > 1) H;

-- [B] DROP 대상 standalone — 멤버 본문 원천. DIFF 면 클라우드에만 있는 수정 → 멤버에 반영 필요(결과 공유)
SELECT 'DMF0072_GET_DATA_TYPE_LIST' OBJ, (SELECT STATUS FROM USER_OBJECTS WHERE OBJECT_NAME = 'DMF0072_GET_DATA_TYPE_LIST' AND OBJECT_TYPE = 'PROCEDURE') CLOUD_STATUS,
       CASE WHEN H.S IS NULL THEN 'ABSENT(이미 삭제됐거나 미이관)' WHEN H.S IN (25710322048, 25710322048) THEN 'SAME(사내 원천과 동일)' ELSE 'DIFF → ⚠ 결과 공유' END VERDICT
  FROM (SELECT SUM(ORA_HASH(RTRIM(TEXT, CHR(10)||CHR(13)||CHR(32)||CHR(9)))) S FROM USER_SOURCE WHERE NAME = 'DMF0072_GET_DATA_TYPE_LIST' AND TYPE = 'PROCEDURE' AND LINE > 1) H;
SELECT 'DMF0072_GET_END_CUSTOMER_LIST' OBJ, (SELECT STATUS FROM USER_OBJECTS WHERE OBJECT_NAME = 'DMF0072_GET_END_CUSTOMER_LIST' AND OBJECT_TYPE = 'PROCEDURE') CLOUD_STATUS,
       CASE WHEN H.S IS NULL THEN 'ABSENT(이미 삭제됐거나 미이관)' WHEN H.S IN (48939494048, 48939494048) THEN 'SAME(사내 원천과 동일)' ELSE 'DIFF → ⚠ 결과 공유' END VERDICT
  FROM (SELECT SUM(ORA_HASH(RTRIM(TEXT, CHR(10)||CHR(13)||CHR(32)||CHR(9)))) S FROM USER_SOURCE WHERE NAME = 'DMF0072_GET_END_CUSTOMER_LIST' AND TYPE = 'PROCEDURE' AND LINE > 1) H;
SELECT 'DMF0072_GET_NNMASTER_MAPPING_WRAPPER' OBJ, (SELECT STATUS FROM USER_OBJECTS WHERE OBJECT_NAME = 'DMF0072_GET_NNMASTER_MAPPING_WRAPPER' AND OBJECT_TYPE = 'PROCEDURE') CLOUD_STATUS,
       CASE WHEN H.S IS NULL THEN 'ABSENT(이미 삭제됐거나 미이관)' WHEN H.S IN (75610017665, 75610017665) THEN 'SAME(사내 원천과 동일)' ELSE 'DIFF → ⚠ 결과 공유' END VERDICT
  FROM (SELECT SUM(ORA_HASH(RTRIM(TEXT, CHR(10)||CHR(13)||CHR(32)||CHR(9)))) S FROM USER_SOURCE WHERE NAME = 'DMF0072_GET_NNMASTER_MAPPING_WRAPPER' AND TYPE = 'PROCEDURE' AND LINE > 1) H;
SELECT 'DMF0072_GET_SALES_SITE_LIST' OBJ, (SELECT STATUS FROM USER_OBJECTS WHERE OBJECT_NAME = 'DMF0072_GET_SALES_SITE_LIST' AND OBJECT_TYPE = 'PROCEDURE') CLOUD_STATUS,
       CASE WHEN H.S IS NULL THEN 'ABSENT(이미 삭제됐거나 미이관)' WHEN H.S IN (52887916372, 52887916372) THEN 'SAME(사내 원천과 동일)' ELSE 'DIFF → ⚠ 결과 공유' END VERDICT
  FROM (SELECT SUM(ORA_HASH(RTRIM(TEXT, CHR(10)||CHR(13)||CHR(32)||CHR(9)))) S FROM USER_SOURCE WHERE NAME = 'DMF0072_GET_SALES_SITE_LIST' AND TYPE = 'PROCEDURE' AND LINE > 1) H;
SELECT 'DMF0072_GET_TEAM_LIST' OBJ, (SELECT STATUS FROM USER_OBJECTS WHERE OBJECT_NAME = 'DMF0072_GET_TEAM_LIST' AND OBJECT_TYPE = 'PROCEDURE') CLOUD_STATUS,
       CASE WHEN H.S IS NULL THEN 'ABSENT(이미 삭제됐거나 미이관)' WHEN H.S IN (105134488227, 105134488227) THEN 'SAME(사내 원천과 동일)' ELSE 'DIFF → ⚠ 결과 공유' END VERDICT
  FROM (SELECT SUM(ORA_HASH(RTRIM(TEXT, CHR(10)||CHR(13)||CHR(32)||CHR(9)))) S FROM USER_SOURCE WHERE NAME = 'DMF0072_GET_TEAM_LIST' AND TYPE = 'PROCEDURE' AND LINE > 1) H;

-- [C] PKG_DMF0072 BODY 의존 객체 — 행이 나오면 MISSING (컴파일 실패 조건)
SELECT COLUMN_VALUE MISSING FROM TABLE(SYS.ODCIVARCHAR2LIST('DM_CUST_MODEL_MAPPING_M', 'GT_DM72_T_MAIN', 'PR_SCM_SYS_LOG_BATCH', 'SCM_ADM_LOOKUP_MASTER_DETAIL', 'SCM_ADM_USER_MNU_EDIT_AUTH_V', 'SCM_MST_SITE', 'SCM_MST_SITE_ITEM', 'SCM_MST_SSO_DEPT_INFO', 'UF_FX_STRING_SPLIT')) WHERE COLUMN_VALUE NOT IN (SELECT OBJECT_NAME FROM USER_OBJECTS);

-- [D] META 현재값 — API_URL 이 standalone 이면 전환 전, PKG.멤버 면 전환 완료
SELECT API_ID, API_URL FROM SCM_ADM_API_M WHERE API_ID IN ('DMF0072_MAIN_SEARCH', 'P_DMF0072_DATATYPE_GET', 'P_DMF0072_ENDCUST_GET', 'P_DMF0072_SALESSITE_GET', 'P_DMF0072_TEAM_GET') ORDER BY API_ID;
SELECT UPPER(PROC_NM) PROC_NM, COUNT(*) CNT FROM SCM_ADM_PROC_M WHERE UPPER(PROC_NM) IN ('DMF0072_GET_DATA_TYPE_LIST', 'DMF0072_GET_END_CUSTOMER_LIST', 'DMF0072_GET_NNMASTER_MAPPING_WRAPPER', 'DMF0072_GET_SALES_SITE_LIST', 'DMF0072_GET_TEAM_LIST') OR PROC_NM IN ('PKG_DMF0072.P_DMF0072_GET_DATA_TYPE_LIST', 'PKG_DMF0072.P_DMF0072_GET_END_CUSTOMER_LIST', 'PKG_DMF0072.P_DMF0072_GET_NNMASTER_MAPPING_WRAPPER', 'PKG_DMF0072.P_DMF0072_GET_SALES_SITE_LIST', 'PKG_DMF0072.P_DMF0072_GET_TEAM_LIST') GROUP BY UPPER(PROC_NM) ORDER BY 1;

-- [E] 앱계정
SELECT GRANTEE, TABLE_NAME, PRIVILEGE FROM USER_TAB_PRIVS WHERE GRANTEE = 'SCMP_APP' AND TABLE_NAME = 'PKG_DMF0072';
SELECT OWNER, SYNONYM_NAME FROM ALL_SYNONYMS WHERE OWNER = 'SCMP_APP' AND SYNONYM_NAME = 'PKG_DMF0072';
